    receipt_path TEXT,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    deleted_at DATETIME(6),
    CONSTRAINT fk_financial_items_report FOREIGN KEY (financial_report_id) REFERENCES financial_reports(id) ON DELETE CASCADE ON UPDATE RESTRICT,
    CONSTRAINT ck_financial_items_type CHECK (transaction_type IN ('income','expense')),
    CONSTRAINT ck_financial_items_amount CHECK (amount > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- =========================================================
-- TABLE: program_evaluations
