    CONSTRAINT fk_program_evaluations_verifier FOREIGN KEY (verifier_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT ck_program_evaluations_decision CHECK (decision IN ('approved','revision','rejected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- =========================================================
-- TABLE: opportunity_categories
