) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- =========================================================
-- TABLE: opportunities
-- =========================================================
CREATE TABLE opportunities (

    id BINARY(16) NOT NULL PRIMARY KEY,
    category_id BINARY(16) NOT NULL,
    organization_id BINARY(16),
    created_by_user_id BINARY(16),
    title VARCHAR(220) NOT NULL,
    slug VARCHAR(190) NOT NULL,
    provider_name VARCHAR(180) NOT NULL,
    description TEXT NOT NULL,
    administrative_area_id BINARY(16),
    location_text VARCHAR(220),
    external_url TEXT NOT NULL,
    deadline_at DATETIME(6),
    starts_at DATETIME(6),
    ends_at DATETIME(6),
    publication_status VARCHAR(24) NOT NULL DEFAULT 'draft',
    published_at DATETIME(6),
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    deleted_at DATETIME(6),
    CONSTRAINT fk_opportunities_category FOREIGN KEY (category_id) REFERENCES opportunity_categories(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_opportunities_org FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE SET NULL ON UPDATE RESTRICT,
    CONSTRAINT fk_opportunities_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE SET NULL ON UPDATE RESTRICT,
    CONSTRAINT fk_opportunities_area FOREIGN KEY (administrative_area_id) REFERENCES administrative_areas(id) ON DELETE SET NULL ON UPDATE RESTRICT,
    CONSTRAINT ck_opportunities_dates CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at >= starts_at),
    CONSTRAINT ck_opportunities_status CHECK (publication_status IN ('draft','published','archived')),
    CONSTRAINT ck_opportunities_published CHECK (publication_status <> 'published' OR published_at IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- =========================================================
-- TABLE: opportunity_bookmarks
-- =========================================================
CREATE TABLE opportunity_bookmarks (

    id BINARY(16) NOT NULL PRIMARY KEY,
    user_id BINARY(16) NOT NULL,
    opportunity_id BINARY(16) NOT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    deleted_at DATETIME(6),
    CONSTRAINT fk_opportunity_bookmark_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE ON UPDATE RESTRICT,
    CONSTRAINT fk_opportunity_bookmark_opportunity FOREIGN KEY (opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- =========================================================
-- TABLE: notifications
-- =========================================================
CREATE TABLE notifications (

    id BINARY(16) NOT NULL PRIMARY KEY,
    user_id BINARY(16) NOT NULL,
    notification_type VARCHAR(80) NOT NULL,
    title VARCHAR(220) NOT NULL,
    body TEXT NOT NULL,
    data JSON NOT NULL DEFAULT (JSON_OBJECT()),
    read_at DATETIME(6),
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    deleted_at DATETIME(6),
    CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE ON UPDATE RESTRICT,
    CONSTRAINT ck_notifications_data_object CHECK (JSON_TYPE(data) = 'OBJECT')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- =========================================================
-- TABLE: audit_logs
-- =========================================================
CREATE TABLE audit_logs (

    id BINARY(16) NOT NULL PRIMARY KEY,
    actor_user_id BINARY(16),
    action VARCHAR(80) NOT NULL,
    entity_type VARCHAR(120) NOT NULL,
    entity_id BINARY(16),
    request_id BINARY(16),
    ip_address VARCHAR(45),
    user_agent TEXT,
    before_data JSON,
    after_data JSON,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT fk_audit_logs_actor FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL ON UPDATE RESTRICT,
    CONSTRAINT ck_audit_logs_before CHECK (before_data IS NULL OR JSON_TYPE(before_data) = 'OBJECT'),
    CONSTRAINT ck_audit_logs_after CHECK (after_data IS NULL OR JSON_TYPE(after_data) = 'OBJECT')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;



